def bubble_sort(arr):
  n=len(arr)-1
  for i in range(n):          # initializing the loop for n times n=5-1=4
    for j in range(n-i):       # initializing the loop for n-i times 
      if arr[j] > arr[j+1]:        # comparing the adjacent elements
        arr[j],arr[j+1]=arr[j+1],arr[j]     #swapping the elements if they are in wrong order
  return arr

print(bubble_sort([10,2,3,4,5]))
  

# Bubble Sort** অ্যালগরিদমে পাশাপাশি (adjacent) থাকা দুটি উপাদান (element) তুলনা করা হয়। যদি বাম পাশের উপাদানটি ডান পাশের উপাদানের চেয়ে বড় হয়, তাহলে তাদের অবস্থান অদলবদল (swap) করা হয়। এই প্রক্রিয়াটি বারবার চলতে থাকে যতক্ষণ না পুরো অ্যারে সাজানো (sorted) হয়ে যায়। ধরা যাক, `arr = [10, 2, 3, 4, 5]`। এখানে `n = len(arr) - 1 = 4`। তাই বাইরের লুপ `for i in range(n)` মোট **৪ বার** চলবে, অর্থাৎ `i = 0, 1, 2, 3`।

# প্রথম পাসে (`i = 0`) ভেতরের লুপ `range(n - i)` অর্থাৎ `range(4)` হবে, তাই `j = 0, 1, 2, 3`। প্রথমে `10` ও `2` তুলনা করা হয়। যেহেতু `10 > 2`, তাই swap করে অ্যারে হয় `[2, 10, 3, 4, 5]`। এরপর `10` ও `3` তুলনা করে swap করলে `[2, 3, 10, 4, 5]` হয়। তারপর `10` ও `4` তুলনা করে swap করলে `[2, 3, 4, 10, 5]` হয় এবং শেষে `10` ও `5` তুলনা করে swap করলে `[2, 3, 4, 5, 10]` পাওয়া যায়। অর্থাৎ প্রথম পাস শেষে সবচেয়ে বড় সংখ্যা `10` একেবারে শেষ অবস্থানে চলে যায়।

# দ্বিতীয় পাসে (`i = 1`) ভেতরের লুপ `range(3)` হবে, তাই `j = 0, 1, 2`। এবার `2` ও `3`, `3` ও `4`, এবং `4` ও `5` তুলনা করা হয়। যেহেতু সবগুলোই সঠিক ক্রমে আছে, তাই কোনো swap হয় না এবং অ্যারে `[2, 3, 4, 5, 10]`-ই থাকে। তৃতীয় পাসে (`i = 2`) ভেতরের লুপ `range(2)` হবে, তাই `j = 0, 1`। এখানে `2 > 3` এবং `3 > 4`—দুটিই মিথ্যা, তাই কোনো পরিবর্তন হয় না। চতুর্থ ও শেষ পাসে (`i = 3`) ভেতরের লুপ `range(1)` হবে, তাই শুধু `j = 0` চলবে। `2 > 3` মিথ্যা হওয়ায় কোনো swap হয় না।

# প্রতিটি পাস শেষে একটি করে বড় উপাদান তার সঠিক অবস্থানে চলে যায়। তাই পরবর্তী পাসে সেই অংশটি আর পরীক্ষা করার প্রয়োজন হয় না। এই কারণেই ভেতরের লুপ `range(n - i)` ব্যবহার করা হয়। ফলে প্রথম পাসে **৪টি**, দ্বিতীয় পাসে **৩টি**, তৃতীয় পাসে **২টি** এবং চতুর্থ পাসে **১টি** তুলনা করা হয়। মোট তুলনার সংখ্যা হয় **৪ + ৩ + ২ + ১ = ১০**। সব পাস শেষ হলে চূড়ান্ত সাজানো অ্যারে হয় **`[2, 3, 4, 5, 10]
